{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let names = null
const ballots = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  const err = (m) => fail(`error: line ${n}: ${m}`)
  if (w[0] === 'candidates') {
    if (names !== null) err('candidates must be declared once, before any ballot')
    if (w.length < 2) err('expected candidates <name>...')
    const seen = new Set()
    for (const nm of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(nm)) err(`invalid candidate name ${nm}`)
      if (seen.has(nm)) err(`candidate ${nm} is declared twice`)
      seen.add(nm)
    }
    names = w.slice(1)
  } else if (w[0] === 'ballot') {
    if (names === null) err('candidates must be declared once, before any ballot')
    if (w.length < 3) err('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(w[1])) err('count must be a positive integer')
    const seen = new Set()
    for (const nm of w.slice(2)) {
      if (!names.includes(nm)) err(`unknown candidate ${nm}`)
      if (seen.has(nm)) err(`candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else err(`unknown directive ${w[0]}`)
})
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = new Map(names.map((c) => [c, []]))
const out = []
let roundNo = 0
let result
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  for (const [c, v] of counts) history.get(c).push(v)
  const cmpName = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
  const listed = [...counts.keys()].sort((a, b) => (counts.get(a) === counts.get(b) ? cmpName(a, b) : counts.get(a) > counts.get(b) ? -1 : 1))
  out.push(`round ${roundNo}: ${listed.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) { result = 'no winner'; break }
  const win = listed.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) { result = `winner ${win}`; break }
  let min = counts.get(listed[0])
  for (const c of listed) if (counts.get(c) < min) min = counts.get(c)
  let cand = listed.filter((c) => counts.get(c) === min)
  while (cand.length > 1) {
    let r = 0
    for (; r < roundNo; r++) {
      const vs = cand.map((c) => history.get(c)[r])
      if (vs.some((v) => v !== vs[0])) break
    }
    if (r === roundNo) break
    const m = cand.map((c) => history.get(c)[r]).reduce((a, b) => (b < a ? b : a))
    cand = cand.filter((c) => history.get(c)[r] === m)
  }
  const elim = cand.length === 1 ? cand[0] : cand.sort(cmpName)[cand.length - 1]
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
out.push(result)
process.stdout.write((mode === 'tally' ? `rounds ${roundNo}\n${result}` : out.join('\n')) + '\n')
EOF
node --test test/*.test.js 2>&1 | tail -8","description":"Write cli and run tests"}

