{"command":"cat package.json; mkdir -p src; cat > src/uri.js <<'EOF'
export function parse(s) {
  let scheme, authority, query, fragment
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    const end = e < 0 ? s.length : e + 2
    authority = s.slice(2, end)
    s = s.slice(end)
  }
  const h = s.indexOf('#')
  if (h >= 0) { fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { query = s.slice(q + 1); s = s.slice(0, q) }
  return { scheme, authority: authority === undefined ? undefined : splitAuthority(authority), path: s, query, fragment }
}

function splitAuthority(a) {
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const from = rest.lastIndexOf(']')
  const c = rest.indexOf(':', from < 0 ? 0 : from + 1)
  let host = rest, port
  if (c >= 0) { host = rest.slice(0, c); port = rest.slice(c + 1) }
  return { userinfo, host, port }
}

export function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    return { ...ref, path: removeDots(ref.path) }
  }
  t.scheme = base.scheme
  if (ref.authority !== undefined) {
    return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  }
  t.authority = base.authority
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let merged
      if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
      }
      t.path = removeDots(merged)
    }
    t.query = ref.query
  }
  t.fragment = ref.fragment
  return t
}

const bad = /%(?![0-9A-Fa-f]{2})/
export function check(u) {
  const parts = [
    ['path', u.path],
    ['userinfo', u.authority && u.authority.userinfo],
    ['host', u.authority && u.authority.host],
    ['query', u.query],
    ['fragment', u.fragment],
  ]
  for (const [name, v] of parts) if (v !== undefined && bad.test(v)) return name
  return null
}

function pct(s) {
  if (s === undefined) return s
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lower = s => s.replace(/[A-Z]/g, c => c.toLowerCase())
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(u) {
  const scheme = u.scheme === undefined ? undefined : lower(u.scheme)
  let authority
  if (u.authority) {
    let { userinfo, host, port } = u.authority
    userinfo = pct(userinfo)
    host = lower(pct(host))
    port = pct(port)
    if (port === '' || (scheme !== undefined && DEFAULT[scheme] === port)) port = undefined
    authority = { userinfo, host, port }
  }
  let path = removeDots(pct(u.path))
  if (authority && path === '') path = '/'
  return { scheme, authority, path, query: pct(u.query), fragment: pct(u.fragment) }
}

export function serialize(u) {
  let s = ''
  if (u.scheme !== undefined) s += u.scheme + ':'
  if (u.authority) {
    const a = u.authority
    s += '//' + (a.userinfo !== undefined ? a.userinfo + '@' : '') + a.host + (a.port !== undefined ? ':' + a.port : '')
  }
  s += u.path
  if (u.query !== undefined) s += '?' + u.query
  if (u.fragment !== undefined) s += '#' + u.fragment
  return s
}
