cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'
import { parse, resolve, check, normalize, serialize } from './uri.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
function fail(n, msg) {
  process.stderr.write(`error: line ${n}: ${msg}\n`)
  process.exit(2)
}
lines.forEach((line, i) => {
  const n = i + 1
  let u
  if (mode === 'resolve') {
    const sp = line.indexOf(' ')
    if (sp < 0) fail(n, 'expected a base and a reference')
    const base = parse(line.slice(0, sp))
    if (base.scheme === undefined) fail(n, 'the base has no scheme')
    u = resolve(base, parse(line.slice(sp + 1)))
  } else u = parse(line)
  const c = check(u)
  if (c) fail(n, `the ${c} has a truncated percent-encoding`)
  out.push(serialize(normalize(u)))
})
if (out.length) process.stdout.write(out.join('\n') + '\n')
EOF
