  assert.equal(run(['merge'], ['X', 'b', 'c'], ['a', 'b', 'c'], ['a', 'b', 'Z']).out, 'X\nb\nZ\n')
})

test('the same change on both sides is not a conflict', () => {
  assert.deepEqual(run(['merge'], ['a', 'X'], ['a', 'b'], ['a', 'X']), { code: 0, out: 'a\nX\n', err: '' })
})

