class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let cands = null
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const w = t[0]
    if (w === 'candidates') {
      if (cands !== null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      cands = [...seen]
    } else if (w === 'ballot') {
      if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${w}`)
    }
  })
  if (cands === null) fail('error: no candidates')
  return { cands, ballots }
}

function run(cands, ballots) {
  const alive = new Set(cands)
  const history = [] // Map name -> votes per round
  const out = []
  let winner = null
  for (let k = 1; ; k++) {
    const votes = new Map([...alive].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => alive.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    const total = ballots.reduce((s, b) => s + b.count, 0n)
    history.push(votes)
    const list = [...votes.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    const line = `round ${k}: ${list.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`
    if (active === 0n) { out.push({ line }); break }
    const top = list[0]
    if (top[1] * 2n > active) { out.push({ line }); winner = top[0]; break }
    let tied = [...alive]
    let min = list[list.length - 1][1]
    tied = tied.filter((c) => votes.get(c) === min)
    for (let r = 0; r < history.length && tied.length > 1; r++) {
      const m = tied.reduce((a, c) => (history[r].get(c) < a ? history[r].get(c) : a), history[r].get(tied[0]))
      tied = tied.filter((c) => history[r].get(c) === m)
    }
    const elim = tied.sort().pop()
    alive.delete(elim)
    out.push({ line, elim })
  }
  return { out, winner, rounds: history.length }
}

const mode = process.argv.length === 3 ? process.argv[2] : null
try {
  if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')
  const { cands, ballots } = parse(readFileSync(0, 'utf8'))
  const r = run(cands, ballots)
  let s = ''
  if (mode === 'rounds') {
    for (const o of r.out) { s += o.line + '\n'; if (o.elim) s += `eliminated ${o.elim}\n` }
  } else s += `rounds ${r.rounds}\n`
  s += r.winner === null ? 'no winner\n' : `winner ${r.winner}\n`
  process.stdout.write(s)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
