{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const fail = (r) => { throw new Fail(`line ${i + 1}: ${r}`) }
    const num = (v, field, least) => {
      if (!COUNT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = t[0]
    if (!['bucket', 'window', 'route', 'event'].includes(d)) fail(`unknown directive ${d}`)
    if (d !== 'event' && events.length > 0) fail('declarations must come before the first event')
    if (d === 'bucket') {
      if (t.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
      const capacity = num(t[2], 'capacity', 1)
      const refill = num(t[3], 'refill', 0)
      const per = num(t[4], 'per', 1)
      if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per })
    } else if (d === 'window') {
      if (t.length !== 4) fail('expected window <name> <limit> <span>')
      if (!NAME.test(t[1])) fail(`invalid policy name ${t[1]}`)
      const limit = num(t[2], 'limit', 0)
      const span = num(t[3], 'span', 1)
      if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { name: t[1], kind: 'window', limit, span })
    } else if (d === 'route') {
      if (t.length < 3) fail('expected route <prefix> <policy>...')
      if (!NAME.test(t[1])) fail(`invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
      for (const p of t.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
      routes.set(t[1], t.slice(2).map((p) => policies.get(p)))
    } else {
      if (t.length !== 3) fail('expected event <tick> <key>')
      const tick = num(t[1], 'tick', 0)
      if (!NAME.test(t[2])) fail(`invalid key ${t[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: t[2] })
    }
  })
  return { routes, events }
}

function run(text) {
  const { routes, events } = parse(text)
  const states = new Map() // key -> Map(policy -> state)
  const out = []
  const stats = new Map()
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, list] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, list }
    }
    let denier = null
    if (best) {
      let ks = states.get(key)
      if (!ks) states.set(key, (ks = new Map()))
      const sts = best.list.map((p) => {
        let s = ks.get(p)
        if (!s) {
          s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
          ks.set(p, s)
        }
        if (p.kind === 'bucket') {
          const max = p.capacity * p.per
          s.num += p.refill * (tick - s.last)
          if (s.num > max) s.num = max
          s.last = tick
        } else {
          const cut = tick - p.span
          s.ticks = s.ticks.filter((x) => x > cut)
        }
        return s
      })
      for (let i = 0; i < sts.length && !denier; i++) {
        const p = best.list[i]
        const ok = p.kind === 'bucket' ? sts[i].num >= p.per : BigInt(sts[i].ticks.length) < p.limit
        if (!ok) denier = p
      }
      if (!denier) {
        best.list.forEach((p, i) => {
          if (p.kind === 'bucket') sts[i].num -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    out.push(`${tick} ${key} ${denier ? 'deny ' + denier.name : 'allow'}`)
    const st = stats.get(key) || { a: 0, d: 0 }
    if (denier) st.d++; else st.a++
    stats.set(key, st)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let res = ''
  let ta = 0, td = 0
  for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const s = stats.get(k)
    ta += s.a; td += s.d
    res += `${k} allowed=${s.a} denied=${s.d}\n`
  }
  return res + `total allowed=${ta} denied=${td}\n`
}

try {
  process.stdout.write(run(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
EOF
