const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(src) {
  const cs = Array.from(src)
  const n = cs.length
  const toks = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

