    }
    if (isDigit(c)) {
      let s = ''
      const run = (pred) => {
        // digit (_? digit)*, starting at a digit
        if (!pred(cs[i])) return false
        s += adv()
        while (i < n) {
          if (pred(cs[i])) s += adv()
          else if (cs[i] === '_' && pred(cs[i + 1])) { s += adv(); s += adv() }
          else break
        }
