const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  const m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/\//)
    const end = e < 0 ? s.length : e + 2
    r.authority = s.slice(2, end)
    s = s.slice(end)
  }
  r.path = s
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = a.slice(at + 1)
  const from = hp.lastIndexOf(']')
  const c = hp.indexOf(':', from < 0 ? 0 : from)
  return c >= 0
    ? { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) }
    : { userinfo, host: hp, port: undefined }
}

export function removeDots(path) {
  let inp = path
