function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const res = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ bs, be: i, ss, se: j, who })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return res
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const sides = [mine, theirs]
  const items = [] // {kind, lines, base}
  let pos = 0, k = 0
  const stable = (to) => {
    if (to > pos) items.push({ kind: 'stable', lines: base.slice(pos, to) })
  }
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    pos = re
    if (group.length === 1) {
      const c = group[0]
      items.push({ kind: c.who ? 'theirs' : 'mine', lines: sides[c.who].slice(c.ss, c.se) })
      continue
    }
    const rep = sides.map((s, w) => {
      const cs = group.filter(c => c.who === w)
      if (!cs.length) return base.slice(rs, re)
      const minBs = Math.min(...cs.map(c => c.bs)), minSs = Math.min(...cs.map(c => c.ss))
      const maxBe = Math.max(...cs.map(c => c.be)), maxSe = Math.max(...cs.map(c => c.se))
      return s.slice(minSs - (minBs - rs), maxSe + (re - maxBe))
    })
