    const [m, t] = rep
    if (eq(m, t)) items.push({ kind: 'both', lines: m })
    else if (eq(m, b)) items.push({ kind: 'theirs', lines: t })
    else if (eq(t, b)) items.push({ kind: 'mine', lines: m })
    else items.push({ kind: 'conflict', m, b, t })
  }
  stable(base.length)
  const out = []
  let conflict = false
  for (const it of items) {
    if (it.kind === 'conflict') {
      conflict = true
      if (mode === 'regions') {
        out.push(`conflict mine=${it.m.length} base=${it.b.length} theirs=${it.t.length}`)
      } else {
        out.push('<<<<<<< mine', ...it.m)
        if (mode === 'merge') out.push('||||||| base', ...it.b)
