import { readFileSync } from 'node:fs'

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(src) {
  const cs = Array.from(src)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  const digitRun = (pred) => {
    // consumes digits with single underscores between digits
    while (i < n) {
      if (pred(cs[i])) adv()
      else if (cs[i] === '_' && pred(cs[i - 1]) && pred(cs[i + 1])) adv()
      else break
    }
  }

  while (i < n) {
    const c = cs[i]
    const sl = line, sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isIdStart(c)) {
      let t = ''
      while (i < n && isIdPart(cs[i])) t += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(t) ? 'keyword' : 'ident', body: t })
      continue
    }
    if (isDigit(c)) {
      const start = i
      let ok = true
      const p = cs[i + 1]
      if (c === '0' && (p === 'x' || p === 'X' || p === 'b' || p === 'B' || p === 'o' || p === 'O')) {
        const pred = /[xX]/.test(p) ? isHex : /[bB]/.test(p) ? isBin : isOct
        adv(); adv()
        if (!pred(cs[i])) ok = false
        else digitRun(pred)
      } else {
        digitRun(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { adv(); digitRun(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { adv(); digitRun(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { adv(); adv(); digitRun(isDigit) }
        }
      }
      if (i < n && isIdPart(cs[i])) {
        ok = false
        while (i < n && isIdPart(cs[i])) adv()
      }
      const text = cs.slice(start, i).join('')
      if (!ok) throw new ScanError(sl, sc, `invalid number ${text}`)
      tokens.push({ line: sl, col: sc, kind: 'number', body: text })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const ch = cs[i]
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch === '"') { adv(); break }
        if (ch !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) throw bad()
          v += String.fromCharCode(parseInt(adv() + adv(), 16))
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') throw bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) throw bad()
          while (i <= j) adv()
          v += String.fromCodePoint(cp)
        } else throw bad()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) { adv(); adv(); tokens.push({ line: sl, col: sc, kind: 'punct', body: two }); continue }
    if (PUNCT1.includes(c)) { adv(); tokens.push({ line: sl, col: sc, kind: 'punct', body: c }); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const src = readFileSync(0, 'utf8')
  let tokens
  try {
    tokens = scan(src)
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    }
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

main()
