export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return (letters.charCodeAt(0) - 64) * 26 + (letters.charCodeAt(1) - 64) + 0
}
export function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
// returns {col,row,name} or null when not a valid in-range address
export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = letters.length === 1 ? letters.charCodeAt(0) - 64 : 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
  return { col, row, name: letters + row }
}
export function addrKey(col, row) { return colName(col) + row }
