    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'bool', v: n.v }
      case 'paren': return ev(n.e)
      case 'ref': {
        const a = parseAddr(n.w)
        return a ? cellValue(a.name) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'un': {
        const v = ev(n.e)
        if (v.t === 'err') return v
        const x = toNum(v)
        if (typeof x !== 'number') return x
