#!/usr/bin/env node
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'replay' && mode !== 'summary') fail('error: usage: cli.js replay|summary')

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/
const policies = new Map()
const routes = new Map()
const out = []
const stats = new Map()
let total = [0, 0]
let started = false
let lastTick = null

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

function err(n, r) { fail(`error: line ${n}: ${r}`) }
function num(n, field, s, least) {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) err(n, `${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function step(p, states, key, tick) {
  let s = states.get(key)
  if (p.type === 'bucket') {
    if (!s) { s = { num: p.capacity * p.per, last: tick }; states.set(key, s) }
    else {
      s.num += p.refill * (tick - s.last)
      s.last = tick
      const cap = p.capacity * p.per
      if (s.num > cap) s.num = cap
    }
  } else {
    if (!s) { s = { ticks: [] }; states.set(key, s) }
    const cut = tick - p.span
    s.ticks = s.ticks.filter(t => t > cut)
  }
  return s
}

for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line[0] === '#') continue
  const f = line.split(/\s+/)
  const d = f[0]
  if (d === 'bucket' || d === 'window' || d === 'route') {
    if (started) err(n, 'declarations must come before the first event')
  }
  if (d === 'bucket') {
    if (f.length !== 5) err(n, 'expected bucket <name> <capacity> <refill> <per>')
    if (!NAME.test(f[1])) err(n, `invalid policy name ${f[1]}`)
    const capacity = num(n, 'capacity', f[2], 1)
    const refill = num(n, 'refill', f[3], 0)
    const per = num(n, 'per', f[4], 1)
    if (policies.has(f[1])) err(n, `policy ${f[1]} is declared twice`)
    policies.set(f[1], { name: f[1], type: 'bucket', capacity, refill, per, states: new Map() })
  } else if (d === 'window') {
    if (f.length !== 4) err(n, 'expected window <name> <limit> <span>')
    if (!NAME.test(f[1])) err(n, `invalid policy name ${f[1]}`)
    const limit = num(n, 'limit', f[2], 0)
    const span = num(n, 'span', f[3], 1)
    if (policies.has(f[1])) err(n, `policy ${f[1]} is declared twice`)
    policies.set(f[1], { name: f[1], type: 'window', limit, span, states: new Map() })
  } else if (d === 'route') {
    if (f.length < 3) err(n, 'expected route <prefix> <policy>...')
    if (!NAME.test(f[1])) err(n, `invalid route prefix ${f[1]}`)
    if (routes.has(f[1])) err(n, `prefix ${f[1]} is routed twice`)
    for (const p of f.slice(2)) if (!policies.has(p)) err(n, `unknown policy ${p}`)
    routes.set(f[1], f.slice(2).map(p => policies.get(p)))
  } else if (d === 'event') {
    if (f.length !== 3) err(n, 'expected event <tick> <key>')
    const tick = num(n, 'tick', f[1], 0)
    const key = f[2]
    if (!NAME.test(key)) err(n, `invalid key ${key}`)
    if (lastTick !== null && tick < lastTick) err(n, `tick ${f[1]} is before tick ${lastTick}`)
    lastTick = tick
    started = true
    let best = null
    for (const [pre, ps] of routes) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    let denied = null
    if (best !== null) {
      const ps = routes.get(best)
      const ss = ps.map(p => step(p, p.states, key, tick))
      for (let j = 0; j < ps.length; j++) {
        const p = ps[j], s = ss[j]
        const ok = p.type === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) { denied = p.name; break }
      }
      if (denied === null) {
        for (let j = 0; j < ps.length; j++) {
          if (ps[j].type === 'bucket') ss[j].num -= ps[j].per
          else ss[j].ticks.push(tick)
        }
      }
    }
    out.push(denied === null ? `${f[1]} ${key} allow` : `${f[1]} ${key} deny ${denied}`)
    let st = stats.get(key)
    if (!st) stats.set(key, (st = [0, 0]))
    st[denied === null ? 0 : 1]++
    total[denied === null ? 0 : 1]++
  } else {
    err(n, `unknown directive ${d}`)
  }
}

if (mode === 'summary') {
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  for (const k of keys) out.push(`${k} allowed=${stats.get(k)[0]} denied=${stats.get(k)[1]}`)
  out.length = 0 + keys.length
  out.length = 0
  for (const k of keys) out.push(`${k} allowed=${stats.get(k)[0]} denied=${stats.get(k)[1]}`)
  out.push(`total allowed=${total[0]} denied=${total[1]}`)
}
process.stdout.write(out.map(l => l + '\n').join(''))
EOF
