import { parseAddress } from './addr.js'

const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function formatValue(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    case 'e': return v.v
    default: return v.v
  }
}

function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}

function cmpStr(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

const rank = { n: 0, s: 1, b: 2 }

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  cellValue(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const c = this.cells.get(key)
    if (!c) return num(0)
    if (this.busy.has(key)) return err('#CYCLE!')
    this.busy.add(key)
    let v
    const s = c.content
    if (s[0] === '=') {
      const p = parseFormula(s.slice(1))
      v = p.ok ? this.node(p.ast) : err('#ERR!')
      if (p.ok && hasBadRange(p.ast)) v = err('#ERR!')
    } else if (s === '') v = num(0)
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = num(Number(s))
    else if (ERRORS.has(s)) v = err(s)
    else v = { t: 's', v: s }
    this.busy.delete(key)
    this.memo.set(key, v)
    return v
  }

  toNum(v) {
    if (v.t === 'n') return v
    if (v.t === 'b') return num(v.v ? 1 : 0)
    return err('#VALUE!')
  }

  fin(x) {
    return Number.isFinite(x) ? num(x) : err('#DIV/0!')
  }

  node(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': {
        const a = parseAddress(n.name)
        return a ? this.cellValue(a.key) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'un': {
        const v = this.node(n.e)
        if (v.t === 'e') return v
        const x = this.toNum(v)
        if (x.t === 'e') return x
        return n.op === '-' ? num(-x.v) : x
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.node(n.l)
    if (l.t === 'e') return l
    const r = this.node(n.r)
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      let c
      if (l.t !== r.t) c = rank[l.t] < rank[r.t] ? -1 : 1
      else if (l.t === 'n') c = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
      else if (l.t === 's') c = cmpStr(l.v, r.v)
      else c = l.v === r.v ? 0 : l.v ? 1 : -1
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = this.toNum(l)
    if (a.t === 'e') return a
    const b = this.toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return this.fin(a.v + b.v)
      case '-': return this.fin(a.v - b.v)
      case '*': return this.fin(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : this.fin(a.v / b.v)
      default: return this.fin(Math.pow(a.v, b.v))
    }
  }

  expand(arg) {
    if (arg.k !== 'range') return [this.node(arg)]
    const a = parseAddress(arg.a)
    const b = parseAddress(arg.b)
    if (!a || !b) return [err('#REF!')]
    const out = []
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) {
      for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
        out.push(this.cellValue(colName(c) + r))
      }
    }
    return out
  }

  call(n) {
    const name = n.name
    const k = n.args.length
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if ((name === 'ABS' && k !== 1) || (name === 'IF' && k !== 3)) return err('#ERR!')
    if (name === 'IF') {
      if (n.args.some((a) => a.k === 'range')) return err('#ERR!')
      const c = this.node(n.args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return this.node(truth ? n.args[1] : n.args[2])
    }
    if (name === 'ABS' && n.args[0].k === 'range') return err('#ERR!')
    const vals = []
    for (const a of n.args) vals.push(...this.expand(a))
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = this.toNum(v)
      if (x.t === 'e') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'ABS': return num(Math.abs(nums[0]))
      case 'SUM': return this.fin(nums.reduce((s, x) => s + x, 0))
      case 'AVG': return this.fin(nums.reduce((s, x) => s + x, 0) / nums.length)
      case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s), Infinity))
      default: return num(nums.reduce((s, x) => (x > s ? x : s), -Infinity))
    }
  }
}

function hasBadRange(n) {
  if (n.k === 'range') return true
  if (n.k === 'bin') return hasBadRange(n.l) || hasBadRange(n.r)
  if (n.k === 'un') return hasBadRange(n.e)
  if (n.k === 'call') return n.args.some((a) => (a.k === 'range' ? false : hasBadRange(a)))
  return false
}
"}

