{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Evaluator, formatValue } from './eval.js'
import { parseAddress } from './addr.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}

function collect(n, refs) {
  if (n.k === 'ref') {
    const a = parseAddress(n.name)
    if (a) refs.set(a.key, a)
  } else if (n.k === 'range') {
    const a = parseAddress(n.a)
    const b = parseAddress(n.b)
    if (a && b) {
      for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) {
        for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
          const key = colName(c) + r
          refs.set(key, { col: c, row: r, key })
        }
      }
    }
  } else if (n.k === 'call') {
    n.args.forEach((x) => collect(x, refs))
  } else if (n.k === 'bin') {
    collect(n.l, refs)
    collect(n.r, refs)
  } else if (n.k === 'un') {
    collect(n.e, refs)
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const stripped = lines[i].replace(/^[ \t]+/, '')
  if (stripped === '' || stripped[0] === '#') continue
  const raw = /^[^ \t]*/.exec(stripped)[0]
  const rest = stripped.slice(raw.length).replace(/^[ \t]+/, '')
  const a = parseAddress(raw)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${raw}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${raw} is declared twice`)
  cells.set(a.key, { ...a, content: rest })
}

const sorted = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)

let out = ''
if (mode === 'values') {
  const ev = new Evaluator(cells)
  for (const c of sorted) out += `${c.key}=${formatValue(ev.cellValue(c.key))}\n`
} else {
  for (const c of sorted) {
    const refs = new Map()
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p.ok) collect(p.ast, refs)
    }
    const list = [...refs.values()].sort((x, y) => x.col - y.col || x.row - y.row)
    out += `${c.key}:${list.map((r) => ' ' + r.key).join('')}\n`
  }
}
process.stdout.write(out)
"}

